                && row.tar.sol.ft.df == window_blind::SourceBlindDfTarGs::default()
                && row.tar.sol.bk.df == window_blind::SourceBlindDfTarGs::default()
                && row.tar.vis.bk == window_blind::SourceBlindBmDf::<1>::default()
